<script>
 import {onMount} from 'svelte';
 import LabIcon from './LabIcon.svelte';
 import LabInvitation from './LabInvitation.svelte';
 import vueSource from '../vue-demo.js?raw';
 import vueStyles from '../styles/vue-product.css?raw';
 import {getLanguage} from '../i18n.js';
 import processSource from './ProcessSimulation.svelte?raw';
 import processStyles from '../styles/simulations.css?raw';
 import {compileLabCode,snippets} from '../lab-code.js';
 let {index}= $props();
 let dialog,terminalInput,opener;let field=$state();let language=$state(getLanguage()),value=$state(''),command=$state(''),error=$state(''),log=$state(''),result=$state(false),file=$state(1);
 const c=$derived(({pt:{title:['Uma sessão que começa no seu código.','Um fluxo que faz o trabalho avançar.','Sistemas que finalmente conversam.'],intro:'Um projeto quase pronto. A última peça é sua.',invite:'Vamos construir algo juntos?',start:'Começar experiência',back:'Voltar ao laboratório',files:'EXPLORADOR',guide:'SUA MISSÃO',task:['Dê um nome ao estúdio da página.','Escreva o pedido que vai iniciar o fluxo.','Preencha o nome do novo contato.'],help:'Complete o trecho destacado. Depois digite executar no terminal ou use o botão.',fill:'Preencher comigo',run:'Executar projeto',reset:'Recomeçar',preview:'Prévia',editor:'Editor',safe:'Simulação local · sem instalações · nenhum dado enviado',missing:'Complete o trecho destacado antes de executar.',unknown:'Use executar ou run para abrir a prévia.',done:'Projeto preparado. Abrindo a prévia…',placeholder:['Nome do estúdio','Pedido de exemplo','Nome do contato'],examples:['Forma Studio','Quero um site para meu negócio','Ana Costa'],ready:'Seu projeto está pronto para receber o último detalhe.'},en:{title:['A session that starts with your code.','A workflow that moves work forward.','Systems that finally connect.'],intro:'An almost finished project. The last piece is yours.',invite:'Shall we build something together?',start:'Start experience',back:'Back to the lab',files:'EXPLORER',guide:'YOUR MISSION',task:['Name the page’s studio.','Write the request that starts the workflow.','Fill in the new contact’s name.'],help:'Complete the highlighted section. Then type run in the terminal or use the button.',fill:'Fill it with me',run:'Run project',reset:'Start over',preview:'Preview',editor:'Editor',safe:'Local simulation · no installation · no data sent',missing:'Complete the highlighted section before running.',unknown:'Use run or executar to open the preview.',done:'Project prepared. Opening preview…',placeholder:['Studio name','Example request','Contact name'],examples:['Forma Studio','I need a website for my business','Anna Costa'],ready:'Your project is ready for the final detail.'},es:{title:['Una sesión que empieza en tu código.','Un flujo que hace avanzar el trabajo.','Sistemas que por fin se conectan.'],intro:'Un proyecto casi terminado. La última pieza es tuya.',invite:'¿Construimos algo juntos?',start:'Comenzar experiencia',back:'Volver al laboratorio',files:'EXPLORADOR',guide:'TU MISIÓN',task:['Dale un nombre al estudio.','Escribe la solicitud que inicia el flujo.','Completa el nombre del nuevo contacto.'],help:'Completa el fragmento destacado. Después escribe ejecutar en la terminal o usa el botón.',fill:'Completar conmigo',run:'Ejecutar proyecto',reset:'Reiniciar',preview:'Vista previa',editor:'Editor',safe:'Simulación local · sin instalaciones · no se envían datos',missing:'Completa el fragmento destacado antes de ejecutar.',unknown:'Usa ejecutar o run para abrir la vista previa.',done:'Proyecto preparado. Abriendo vista previa…',placeholder:['Nombre del estudio','Solicitud de ejemplo','Nombre del contacto'],examples:['Forma Studio','Necesito un sitio para mi negocio','Ana Costa'],ready:'Tu proyecto está listo para el último detalle.'}})[language]||{});
 const editLabel=$derived(language==='en'?'Your part of the code':language==='es'?'Tu parte del código':'Sua parte no código');
 const exampleLabel=$derived(language==='en'?'Example to guide you':language==='es'?'Ejemplo para guiarte':'Exemplo para se guiar');
 function tokens(line){return line.split(/("[^"\n]*"|'[^'\n]*'|\b(?:const|return|ref|computed|import|from|let|function|if|else|true|false|[0-9]+)\b)/g).map(text=>({text,kind:/^["']/.test(text)?'string':/^\d+$/.test(text)?'number':/^(ref|computed)$/.test(text)?'function':/^(const|return|import|from|let|function|if|else|true|false)$/.test(text)?'keyword':''}));}
 const filenames=$derived([index===0?'booking.js':'ProcessSimulation.svelte',index===1?'workflow.json':index===2?'contact.json':'booking-state.js',index===0?'workspace.css':'styles.css']);
 let compiled=$state(''),explanation=$state(''),previewUrl=$state('');
 const source=$derived(index===0?vueSource:processSource);
 const taskTitle=$derived((language==='en'?['Set the session duration and price.','Configure the workflow rule in JSON.','Map the source fields to the CRM.']:language==='es'?['Define la duración y el precio.','Configura la regla del flujo en JSON.','Conecta los datos al CRM.']:['Defina a duração e o preço.','Configure a regra do fluxo em JSON.','Mapeie os campos de origem para o CRM.'])[index]);
 const taskHelp=$derived((language==='en'?['hours is the duration; hourlyRate is the price per hour. Copy the example, change the numbers and run.','request is the message. Use priority alta/normal and action responder/organizar. Then run.','name receives nome or empresa. stage receives etapa or origem. Change a pair and run.']:language==='es'?['hours es la duración; hourlyRate es el precio por hora. Copia el ejemplo, cambia los números y ejecuta.','request es el mensaje. Usa priority alta/normal y action responder/organizar. Después ejecuta.','Usa nome/empresa en name y etapa/origem en stage. Cambia un par y ejecuta.']:['hours é a duração; hourlyRate é o preço por hora. Copie o exemplo, mude os números e execute.','request é a mensagem. Use priority alta/normal e action responder/organizar. Depois execute.','name recebe nome ou empresa. stage recebe etapa ou origem. Mude um par e execute.'])[index]);
 const explanationTitle=$derived(language==='en'?'Do you know what you just did?':language==='es'?'¿Sabes lo que acabas de hacer?':'Sabe o que você fez?');
 const code=$derived(file===0?source:file===1?value:index===0?vueStyles:processStyles);
 function start(){opener=document.activeElement;dialog.showModal();field?.focus();}
 function close(){result=false;dialog.close();opener?.focus();}
 function run(){const output=compileLabCode(index,value,language);if(output.error){error=output.error;result=false;file=1;return;}error='';compiled=output.html||'';explanation=output.explanation;log=c.done;result=true;const url=new URL('/lab-preview.html',location.origin);url.hash=encodeURIComponent(JSON.stringify({index,code:value,language}));previewUrl=url.href;window.open(previewUrl,'_blank','noopener,noreferrer');}
 function submit(){if(!['run','executar','ejecutar','npm run dev'].includes(command.trim().toLowerCase())){error=c.unknown;return;}command='';run();}
 onMount(()=>{const sync=()=>language=getLanguage();sync();document.addEventListener('languagechange',sync);return()=>document.removeEventListener('languagechange',sync);});
</script>
<LabInvitation {index} {language} {c} onstart={start}/>
<dialog aria-label={c.title[index]} onkeydown={event=>{if(event.key==='Escape')event.stopPropagation();if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();run();}}} class="lab-workbench" bind:this={dialog} oncancel={event=>{event.preventDefault();close();}}>
 <div class="safari-bar"><button type="button" class="workbench-back" onclick={close} aria-label={c.back}><LabIcon name="back" size={16}/> {c.back}</button><div class="address-bar"><LabIcon name="window" size={14}/><span>loui / lab / {filenames[1]}</span></div><span class="browser-mark">loui lab</span></div>
 <div class="ide-titlebar"><span class="ide-project"><LabIcon name="code" size={15}/> {['luz-studio','request-flow','connected-workspace'][index]} — loui code</span><span>{c.safe}</span></div>
 <div class="ide-layout">
  <aside class="ide-explorer"><h4>{c.files}</h4><p>⌄ {['luz-studio','request-flow','connected-workspace'][index]}</p>{#each filenames as filename,i}<button type="button" aria-pressed={file===i} class:chosen={file===i} onclick={()=>file=i}><span class="file-kind"><LabIcon name={i===2?'code':'file'} size={15}/></span>{filename}</button>{/each}<div class="explorer-note">{index===0?'Vue 3 / JavaScript / CSS':'Svelte / CSS / JSON'}<br>loui lab</div></aside>
  <main class="ide-main"><div class="ide-tabs"><button type="button" class:chosen={!result} onclick={()=>result=false}><LabIcon name="file" size={14}/>{filenames[file]}<span class="tab-state" aria-hidden="true"></span></button><button class:chosen={result} type="button" onclick={()=>{if(value.trim())run();else error=c.missing;}}><LabIcon name="window" size={14}/>{c.preview}</button></div>
   {#if result}<section class="external-preview-ready"><span aria-hidden="true">↗</span><h3>{language==='en'?'Your preview has its own space.':language==='es'?'Tu vista previa tiene su propio espacio.':'Sua prévia ganhou um espaço só dela.'}</h3><p>{language==='en'?'Opened in a separate tab. If the browser blocked it, use the link below.':language==='es'?'Abierta en otra pestaña. Si el navegador la bloqueó, usa el enlace.':'Aberta em outra aba. Se o navegador bloqueou, use o link abaixo.'}</p><a class="open-external-preview" href={previewUrl} target="_blank" rel="noopener noreferrer">{c.preview} ↗</a><button type="button" onclick={()=>result=false}>{c.editor}</button><div class="what-you-did"><strong>{explanationTitle}</strong><p>{explanation}</p></div></section>
   {:else if file===1}<div class="snippet-editor"><div class="snippet-heading"><label for={'lab-value-'+index}>{editLabel}</label><span>{index===0?'JavaScript':'JSON'}</span></div><div class="editable-code"><div class="edit-line-numbers" aria-hidden="true">{#each Array(Math.max(5,value.split('\n').length)) as _,i}<span>{i+1}</span>{/each}</div><textarea id={'lab-value-'+index} name="code" wrap="off" onscroll={event=>{const gutter=event.currentTarget.parentElement.querySelector('.edit-line-numbers');if(gutter)gutter.scrollTop=event.currentTarget.scrollTop;}} bind:this={field} bind:value spellcheck="false" autocomplete="off" maxlength="800" oninput={()=>{error='';result=false;}} aria-label={taskTitle} aria-describedby={'mission-help-'+index}></textarea></div><div class="snippet-reference"><p id={'snippet-example-'+index}>{exampleLabel}</p><pre>{#each snippets[index].split('\n') as line}<span class="sample-line">{#each tokens(line) as token}<span class={'syntax-'+token.kind}>{token.text}</span>{/each}</span>{/each}</pre></div></div>{:else}<div class="code-pane" role="textbox" aria-readonly="true" aria-multiline="true" tabindex="0" aria-label={filenames[file]}><pre><code>{#each code.split('\n') as line,i}<span class="code-line"><span class="line-number" aria-hidden="true">{i+1}</span><span class:code-tag={line.trim().startsWith('<')} class:code-style={file===2} class:editable-line={file===1&&(line.includes('studio')||line.includes('request')||line.includes('name'))}>{#each tokens(line) as token}<span class={'syntax-'+token.kind}>{token.text}</span>{/each}</span></span>{/each}</code></pre></div>{/if}
   <section class="ide-terminal"><header><span class="terminal-tab">Terminal</span><span>zsh / loui</span></header><p class="terminal-ready">{log||c.ready}</p><form onsubmit={event=>{event.preventDefault();submit();}}><label for={'lab-command-'+index}><span>loui</span> ~ %</label><input id={'lab-command-'+index} name="command" bind:this={terminalInput} bind:value={command} autocomplete="off" spellcheck="false" aria-label="Terminal" placeholder={language==='en'?'run':'executar'}/><button type="submit" aria-label={c.run}>↵</button></form><p class="workbench-error" role="status">{error}</p></section>
  </main>
  <aside class="ide-guide"><p class="guide-kicker">{c.guide}</p><span class="step-badge">01 / 02</span><h3>{taskTitle}</h3><p id={'mission-help-'+index}>{taskHelp}</p><button type="button" class="guide-fill" onclick={()=>{value=snippets[index];file=1;error='';result=false;field?.focus();}}>{c.fill}</button><div class="guide-divider"></div><span class="step-badge">02 / 02</span><button type="button" class="guide-run" onclick={run}><LabIcon name="play" size={14}/>{c.run}</button><button type="button" class="guide-reset" onclick={()=>{value='';command='';error='';log='';result=false;file=1;compiled='';explanation='';field?.focus();}}>{c.reset}</button></aside>
 </div><div class="ide-statusbar"><span>loui lab</span><span>UTF-8 · {file===2?'CSS':index===0?'JavaScript / Vue 3':file===1?'JSON':'HTML'} · local</span></div>
</dialog>
